let ghostMotion=null,ghostFrame=0;const healthVisuals=new Map();let healthTimers=[];
makeGhost=function(el,e){let rect=el.getBoundingClientRect(),g=el.cloneNode(true);g.id='drag-ghost';g.classList.add('drag-ghost');g.classList.remove('drag-source');g.style.width=rect.width+'px';g.style.height=rect.height+'px';g.style.margin='0';g.style.left='0';g.style.top='0';g.style.transition='none';g.style.animation='none';document.body.append(g);ghostMotion={el:g,x:e.clientX,y:e.clientY,tx:e.clientX,ty:e.clientY,ox:e.clientX-rect.left,oy:e.clientY-rect.top,last:performance.now()};g.style.transform=`translate3d(${rect.left}px,${rect.top}px,0)`;cancelAnimationFrame(ghostFrame);ghostFrame=requestAnimationFrame(followGhost)};
function moveGhost(e){if(ghostMotion){ghostMotion.tx=e.clientX;ghostMotion.ty=e.clientY}}
function followGhost(now){let m=ghostMotion;if(!m||!m.el.isConnected)return;let dt=Math.min(40,now-m.last);m.last=now;let alpha=1-Math.exp(-dt/12);m.x+=(m.tx-m.x)*alpha;m.y+=(m.ty-m.y)*alpha;m.el.style.transform=`translate3d(${m.x-m.ox}px,${m.y-m.oy}px,0)`;ghostFrame=requestAnimationFrame(followGhost)}
const clearOriginal=clearDrag;clearDrag=function(){cancelAnimationFrame(ghostFrame);ghostMotion=null;clearOriginal()};
function forecastDamage(r){if(!r)return 0;let block=r.block||0,total=0;for(let e of r.enemies){if(e.hp<=0||e.hp-(e.poison||0)<=0||e.intent!=='attack')continue;for(let n=0;n<(e.hits||1);n++){let absorbed=Math.min(block,e.atk);block-=absorbed;total+=e.atk-absorbed}}return Math.min(r.hp,total)}
hpbar=function(hp,max,block,capacity=max){return `<div class="health-shell ${block>0?'has-block':''}" data-hp="${hp}" data-max="${max}" data-capacity="${capacity}"><div class="health-track"><i class="damage-trail" style="width:${hp/capacity*100}%"></i><i class="hp-fill" style="width:${hp/capacity*100}%"></i></div>${block>0?`<span class="block-badge" aria-label="ブロック ${block}">⬡ <b>${block}</b></span>`:''}</div>`};
const battleMotionBase=battle;battle=function(){let html=battleMotionBase(),n=forecastDamage(S.run);return html.replace('<div class="muted">探索者</div>',`<div class="damage-forecast ${n?'danger':'safe'}" title="現在のブロックと毒による撃破を考慮した、敵ターンの予測HP減少量" aria-label="予測HP減少量 ${n}">${n?'-'+n:'−0'}</div><div class="muted">探索者</div>`)};
function setUnitHealth(key,hp,max,block){let el=document.querySelector(`[data-entity="${key}"]`),shell=el?.querySelector('.health-shell');if(!shell)return;const capacity=max+(key==='player'?(S.run?.curseMaxLoss||0):0);shell.dataset.capacity=capacity;let fill=shell.querySelector('.hp-fill'),trail=shell.querySelector('.damage-trail'),old=healthVisuals.get(String(key));let current=old?.hp??hp;let visual={hp,max,white:Math.max(old?.white??current,hp),token:(old?.token||0)+1};healthVisuals.set(String(key),visual);let token=visual.token;shell.dataset.hp=hp;shell.dataset.max=max;fill.style.width=hp/capacity*100+'%';if(hp<current||visual.white>hp){trail.style.transition='none';trail.style.width=Math.max(current,visual.white)/capacity*100+'%';let timer=setTimeout(()=>{let v=healthVisuals.get(String(key));if(v!==visual||v.token!==token)return;trail.style.transition='width 650ms cubic-bezier(.22,.61,.36,1)';trail.style.width=hp/capacity*100+'%';v.white=hp},520);healthTimers.push(timer)}else{trail.style.width=hp/capacity*100+'%';visual.white=hp}shell.classList.toggle('has-block',block>0);let badge=shell.querySelector('.block-badge');if(block>0){if(!badge){badge=document.createElement('span');badge.className='block-badge';shell.append(badge)}badge.textContent='⬡ '+block;badge.setAttribute('aria-label','ブロック '+block)}else badge?.remove();let label=el.querySelector('p');if(label)label.textContent=`♥ ${hp} / ${max}　◇ ${block}`}
function hydrateHealth(){if(page!=='battle'||!S.run)return;document.querySelectorAll('[data-entity]').forEach(el=>{let key=el.dataset.entity,shell=el.querySelector('.health-shell');if(!shell)return;let hp=+shell.dataset.hp,max=+shell.dataset.max,capacity=+shell.dataset.capacity||max,previous=healthVisuals.get(key),fill=shell.querySelector('.hp-fill'),trail=shell.querySelector('.damage-trail');if(previous){fill.style.transition='none';fill.style.width=previous.hp/capacity*100+'%';trail.style.width=previous.white/capacity*100+'%'}else healthVisuals.set(key,{hp,max,white:hp,token:0});requestAnimationFrame(()=>{if(!shell.isConnected)return;fill.style.transition='width 320ms cubic-bezier(.22,.61,.36,1)';let unit=key==='player'?S.run:S.run.enemies[+key];if(unit)setUnitHealth(key,unit.hp,unit.max,unit.block)})})}
const renderMotionBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderMotionBase();hydrateHealth()};
const animateMotionBase=animateEntity;animateEntity=async function(key,kind,n=0,direction=1){if(S.run&&kind==='hit'){let unit=key==='player'?S.run:S.run.enemies[+key];if(unit)setUnitHealth(key,unit.hp,unit.max,unit.block)}return animateMotionBase(key,kind,n,direction)};
const chooseMotionBase=choose;choose=function(type){healthTimers.forEach(clearTimeout);healthTimers=[];healthVisuals.clear();chooseMotionBase(type)};
